export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"id","term":"Market order","aka":["order pasar","order market"],"short":"Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin.","body":[["Saat Anda mengirim market order beli, exchange mengambil order jual termurah di ",["order book","order-book"],", lalu level berikutnya jika jumlahnya belum cukup. Market order jual bekerja sebaliknya, mengambil order beli tertinggi. Karena mengambil ",["likuiditas","liquidity"]," yang sudah ada, market order hampir selalu dikenai biaya taker."],["Keunggulannya adalah kepastian eksekusi. Market order cocok jika Anda harus segera keluar dari posisi, misalnya saat ",["stop loss","stop-loss"]," tersentuh. Kelemahannya adalah ketidakpastian harga, terutama pada pasangan dengan spread lebar atau saat pasar bergerak cepat."],["Beberapa exchange membatasi seberapa jauh market order boleh bergeser dari ",["harga terakhir","last-price"]," untuk melindungi pengguna. Aturannya berbeda di tiap platform, jadi periksa pengaturan order di exchange yang Anda gunakan."]],"example":["Misalkan ask terbaik ",["BTC","bitcoin"]," adalah 64.000 ",["USDT","usdt"]," untuk 0,3 BTC, dan level berikutnya 64.040 USDT. Anda mengirim market order beli 0,5 BTC. Anda mendapat 0,3 BTC di 64.000 dan 0,2 BTC di 64.040, total 19.200 + 12.808 = 32.008 USDT. Harga rata-ratanya 64.016 USDT. Dengan biaya taker 0,1%, Anda membayar tambahan sekitar 32 USDT."],"mistakes":["Memakai market order untuk jumlah besar pada koin yang sepi.","Mengirim market order tepat saat rilis berita ketika harga melompat-lompat.","Tidak menyadari bahwa market order dikenai biaya taker yang biasanya lebih tinggi daripada maker."],"faq":[{"q":"Apa beda market order dan limit order?","a":"Market order dieksekusi segera di harga terbaik yang tersedia. Limit order hanya dieksekusi di harga yang Anda tentukan atau lebih baik, tetapi bisa saja tidak terisi."},{"q":"Kapan sebaiknya memakai market order?","a":"Saat kecepatan lebih penting daripada harga, misalnya untuk keluar cepat dari posisi atau membeli aset yang sangat likuid dalam jumlah kecil."}],"title":"Apa itu market order? Arti dan kapan memakainya","description":"Pelajari arti market order, cara order dieksekusi di order book, biaya taker, dan kapan market order lebih tepat dipakai.","related":[["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Pasar, limit, batalkan: apa yang diselesaikan masing-masing?"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"id","term":"Arbitrase (arbitrage)","aka":["arbitrage","arbitrase kripto","arb"],"short":"Arbitrase adalah strategi memanfaatkan selisih harga aset yang sama di dua pasar berbeda, misalnya membeli di exchange yang lebih murah dan menjual di exchange yang lebih mahal secara bersamaan.","body":[["Harga kripto tidak selalu sama di setiap exchange karena perbedaan ",["likuiditas","liquidity"],", permintaan lokal, dan kecepatan transfer. Arbitrase klasik memanfaatkan selisih itu. Ada juga variasi lain: arbitrase segitiga di satu exchange (misalnya ",["USDT","usdt"]," ke ",["BTC","bitcoin"]," ke ",["ETH","ethereum"]," lalu kembali ke USDT), arbitrase spot-futures, dan ",["funding rate arbitrage","funding-rate-arbitrage"],"."],["Di atas kertas terlihat bebas risiko, tetapi kenyataannya selisih harga biasanya kecil dan cepat hilang karena bot profesional bersaing ketat. ",["Biaya trading","maker-taker-fees"],", biaya penarikan, biaya jaringan, waktu konfirmasi blockchain, dan slippage bisa menghapus keuntungan."],"Risiko lain termasuk penarikan atau deposit yang ditangguhkan, perbedaan jaringan token, dan harga yang berubah selama transfer. Banyak arbitrase serius dilakukan dengan menyiapkan saldo di kedua exchange sejak awal."],"example":"Misalkan XRP dihargai 0,600 USDT di exchange A dan 0,606 USDT di exchange B, selisih 1%. Anda membeli 10.000 XRP di A seharga 6.000 USDT dengan biaya taker 0,1%, yaitu 6 USDT. Penarikan XRP ke B dikenai biaya, misalnya 0,25 XRP, dan menjual di B dengan biaya 0,1% kira-kira 6,06 USDT. Hasil penjualan sekitar 6.059,85 USDT, dikurangi biaya jual 6,06 menjadi sekitar 6.053,8 USDT. Setelah dikurangi modal 6.000 dan biaya beli 6 USDT, laba bersih sekitar 47,8 USDT, dengan syarat harga tidak berubah selama transfer.","mistakes":["Lupa menghitung biaya penarikan dan biaya jaringan yang bisa melebihi selisih harga.","Mengirim token lewat jaringan yang tidak didukung exchange tujuan.","Menganggap selisih harga di layar bisa dieksekusi penuh, padahal order book di harga itu mungkin tipis."],"faq":[{"q":"Apakah arbitrase kripto benar-benar bebas risiko?","a":"Tidak. Ada risiko harga berubah saat transfer, penarikan ditahan, slippage, dan biaya yang lebih besar dari perkiraan. Selisih harga juga sering hilang dalam hitungan detik."},{"q":"Kenapa harga kripto bisa berbeda di tiap exchange?","a":"Setiap exchange punya order book sendiri dengan pembeli dan penjual yang berbeda. Perbedaan likuiditas, mata uang lokal, dan hambatan transfer membuat harga tidak selalu sama."}],"title":"Apa itu arbitrase kripto? Cara kerja dan risikonya","description":"Pelajari arbitrase kripto antar-exchange, contoh hitungan dengan biaya, jenis-jenis arbitrase, dan risiko yang sering diabaikan.","related":[["funding-rate-arbitrage","Arbitrase funding rate (funding rate arbitrage)","Arbitrase funding rate adalah strategi netral pasar yang membeli aset di spot dan membuka short dengan ukuran sama di perpetual, sehingga risiko harga saling meniadakan dan keuntungan berasal dari pembayaran funding."],["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread."],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"id","term":"Kontrak berjangka perpetual (perpetual futures)","aka":["perpetual","perp","perps","futures perpetual"],"short":"Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short.","body":[["Karena tidak ada jatuh tempo, Anda bisa memegang posisi perpetual selama margin mencukupi. Untuk mencegah harga kontrak menjauh dari harga spot, exchange memakai ",["funding rate","funding-rate"],". Jika harga perpetual lebih tinggi dari indeks spot, long membayar short; jika lebih rendah, short membayar long."],["Funding umumnya diselesaikan setiap 8 jam, tetapi beberapa exchange dan pasangan memakai interval 1, 2, atau 4 jam. Exchange juga memakai ",["mark price","mark-price"],", bukan ",["harga transaksi terakhir","last-price"],", untuk menghitung ",["unrealized PnL","unrealized-pnl"]," dan ",["likuidasi","liquidation"],", agar posisi tidak mudah dilikuidasi oleh lonjakan harga sesaat."],["Perpetual tersedia di ",["exchange terpusat","centralized-exchange"]," seperti Binance, OKX, Bybit, dan Bitget, serta di DEX on-chain seperti Hyperliquid. Ukuran kontrak, leverage maksimal, tingkat maintenance margin, dan batas funding berbeda di tiap platform."]],"example":"Anda membuka long BTC perpetual senilai 10.000 USDT dengan leverage 4x, jadi margin Anda 2.500 USDT. Funding rate saat itu 0,01% per 8 jam. Setiap periode funding, Anda membayar 10.000 x 0,01% = 1 USDT kepada pihak short. Jika posisi dipegang 10 hari, ada 30 periode funding, total sekitar 30 USDT. Jika harga BTC naik 5% dalam 10 hari itu, keuntungan Anda 500 USDT dikurangi funding 30 USDT dan biaya trading.","mistakes":["Memegang posisi perpetual berminggu-minggu tanpa menghitung akumulasi funding fee.","Mengira likuidasi dihitung dari harga transaksi terakhir, padahal kebanyakan exchange memakai mark price.","Menganggap semua exchange memakai interval funding 8 jam yang sama."],"faq":[{"q":"Kenapa disebut perpetual?","a":"Karena kontraknya tidak pernah jatuh tempo. Anda bisa memegang posisi tanpa batas waktu selama margin mencukupi dan posisi tidak dilikuidasi."},{"q":"Apa beda perpetual dan futures kuartalan?","a":"Futures kuartalan punya tanggal settlement dan harganya bisa berbeda dari spot (basis). Perpetual tidak punya tanggal jatuh tempo dan memakai funding rate untuk menjaga harganya dekat dengan spot."}],"title":"Apa itu perpetual futures? Arti kontrak perpetual kripto","description":"Pahami kontrak berjangka perpetual: cara kerja tanpa jatuh tempo, funding rate, mark price, dan risiko yang perlu Anda hitung.","related":[["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["futures-contract","Kontrak futures (kontrak berjangka)","Kontrak futures adalah perjanjian untuk membeli atau menjual aset pada harga yang disepakati, sehingga Anda bisa mengambil posisi naik (long) atau turun (short) tanpa harus memegang asetnya langsung."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"id","term":"Futures berjangka (delivery futures)","aka":["futures kuartalan","quarterly futures","delivery futures","futures jatuh tempo"],"short":"Futures berjangka atau delivery futures adalah kontrak futures dengan tanggal jatuh tempo tetap, misalnya mingguan atau kuartalan, yang diselesaikan pada harga settlement di tanggal tersebut.","body":[["Berbeda dengan ",["perpetual","perpetual-futures"],", kontrak ini tidak memakai ",["funding rate","funding-rate"],". Selisih antara harga futures dan harga spot disebut basis. Saat pasar optimis, harga futures biasanya lebih tinggi dari spot (contango); saat pesimis, bisa lebih rendah (backwardation). Mendekati jatuh tempo, harga futures bergerak menuju harga spot."],["Di exchange kripto, sebagian besar ",["kontrak berjangka","futures-contract"]," diselesaikan secara tunai: posisi ditutup pada harga settlement, biasanya berdasarkan rata-rata ",["harga indeks","index-price"]," dalam periode tertentu sebelum jatuh tempo. Tidak ada koin yang benar-benar dikirim, meski namanya delivery. Metode persisnya berbeda per exchange."],["Kontrak ini populer untuk ",["lindung nilai","hedging"]," dan strategi basis trade, karena biayanya tetap dan bisa dihitung dari awal, berbeda dengan funding yang berubah-ubah."]],"example":["Misalkan ",["BTC","bitcoin"]," spot di 60.000 USDT dan futures kuartalan yang jatuh tempo 90 hari lagi di 61.200 USDT. Basisnya 1.200 USDT atau 2%, kira-kira 8% per tahun. Seorang trader membeli 1 BTC di spot dan short 1 BTC di futures kuartalan. Pada jatuh tempo, kedua harga bertemu. Jika BTC berakhir di 55.000, spot rugi 5.000 dan short futures untung 6.200, sehingga hasil bersih 1.200 USDT sebelum biaya, sama seperti basis awal."],"mistakes":["Lupa tanggal jatuh tempo sehingga posisi ditutup otomatis pada harga settlement yang tidak diharapkan.","Mengira harga futures kuartalan adalah prediksi harga resmi di masa depan.","Membandingkan basis kuartalan dengan funding rate tanpa mengubahnya ke angka tahunan yang setara."],"faq":[{"q":"Apakah futures berjangka benar-benar mengirim koin saat jatuh tempo?","a":"Di kebanyakan exchange kripto, kontrak diselesaikan tunai dalam USDT atau koin jaminan, bukan dengan pengiriman aset fisik. Cek aturan settlement di halaman spesifikasi kontrak exchange Anda."},{"q":"Kenapa harga futures kuartalan berbeda dari spot?","a":"Perbedaan itu disebut basis dan mencerminkan biaya modal serta permintaan leverage. Saat banyak trader ingin long, harga futures cenderung di atas spot."}],"title":"Apa itu delivery futures? Arti futures kuartalan kripto","description":"Pelajari futures berjangka atau kuartalan: cara kerja jatuh tempo, settlement tunai, basis, contango, dan bedanya dengan perpetual.","related":[["futures-contract","Kontrak futures (kontrak berjangka)","Kontrak futures adalah perjanjian untuk membeli atau menjual aset pada harga yang disepakati, sehingga Anda bisa mengambil posisi naik (long) atau turun (short) tanpa harus memegang asetnya langsung."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["futures-basis","Basis futures (futures basis)","Basis futures adalah selisih antara harga kontrak futures dan harga spot aset yang sama, biasanya dinyatakan dalam persen atau persen per tahun."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"id","term":"Margin awal (initial margin)","aka":["initial margin","IM","margin pembukaan"],"short":"Margin awal adalah jumlah jaminan minimum yang harus Anda setor untuk membuka posisi dengan leverage, biasanya sama dengan nilai posisi dibagi leverage yang dipilih.","body":[["Jika Anda membuka posisi senilai 10.000 ",["USDT","usdt"]," dengan ",["leverage","leverage"]," 10x, margin awalnya 1.000 USDT. Semakin tinggi leverage, semakin kecil margin awal, dan semakin sedikit ruang sebelum posisi mendekati ",["likuidasi","liquidation"],". Margin awal juga sering dinyatakan sebagai persentase, misalnya 10% untuk leverage 10x."],["Margin awal berbeda dengan ",["maintenance margin","maintenance-margin"],". Margin awal adalah syarat untuk membuka posisi, sedangkan maintenance margin adalah batas minimum yang harus dijaga agar posisi tidak dilikuidasi. Maintenance margin selalu lebih kecil dari margin awal."],"Exchange biasanya juga menahan perkiraan biaya penutupan saat Anda membuka posisi, sehingga saldo yang terkunci sedikit lebih besar dari perhitungan sederhana. Untuk posisi sangat besar, tingkatan risiko memaksa leverage lebih rendah, sehingga margin awal per dolar posisi naik."],"example":["Anda ingin long 0,5 ",["BTC","bitcoin"]," saat harga 64.000 USDT, nilai posisi 32.000 USDT. Dengan leverage 20x, margin awalnya 32.000 dibagi 20 = 1.600 USDT. Jika Anda menurunkan leverage ke 8x, margin awal naik menjadi 4.000 USDT. Kerugian per 1% pergerakan harga tetap 320 USDT di kedua pilihan, tetapi dengan 8x margin Anda lebih tebal sehingga ",["harga likuidasi","liquidation-price"]," lebih jauh dari harga masuk."],"mistakes":["Menganggap margin awal adalah batas kerugian maksimal di mode cross, padahal saldo lain bisa ikut terpakai.","Memilih leverage tertinggi agar margin awal kecil, lalu terkejut posisi cepat dilikuidasi.","Tidak memperhitungkan saldo tambahan yang ditahan untuk biaya saat membuka posisi."],"faq":[{"q":"Bagaimana cara menghitung margin awal?","a":"Bagi nilai posisi dengan leverage. Posisi 5.000 USDT dengan leverage 5x membutuhkan margin awal 1.000 USDT, ditambah biaya yang mungkin ditahan exchange."},{"q":"Apa beda margin awal dan maintenance margin?","a":"Margin awal dibutuhkan untuk membuka posisi, sedangkan maintenance margin adalah batas minimum agar posisi tetap terbuka. Jika ekuitas posisi turun di bawah maintenance margin, likuidasi terjadi."}],"title":"Apa itu margin awal (initial margin)? Arti dan rumusnya","description":"Pahami margin awal di futures kripto: rumus nilai posisi dibagi leverage, bedanya dengan maintenance margin, dan contoh hitungan.","related":[["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Mengapa posisi Anda bisa ditutup sebelum margin Anda menyentuh nol?"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"id","term":"Portfolio margin","aka":["margin portofolio","PM","portfolio margin mode"],"short":"Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil.","body":[["Pada mode margin biasa, setiap posisi dihitung sendiri-sendiri. Portfolio margin melihat semua posisi bersama, termasuk spot, futures, dan opsi di beberapa exchange, lalu mensimulasikan kerugian dalam berbagai skenario pergerakan harga dan ",["volatilitas","volatility"],". Margin yang dibutuhkan disesuaikan dengan kerugian terburuk dalam skenario itu."],["Manfaatnya terasa bagi trader yang melakukan ",["hedging","hedging"],". Misalnya, memegang ",["BTC","bitcoin"]," spot dan short BTC ",["perpetual","perpetual-futures"]," dengan ukuran sama hampir tidak punya risiko arah, sehingga margin yang diperlukan kecil. Ini membuat modal lebih efisien."],["Namun, efisiensi modal juga bisa mendorong ",["leverage","leverage"]," total yang sangat tinggi. Exchange seperti Binance, OKX, dan Bybit menawarkan bentuk portfolio margin atau ",["unified account","unified-trading-account"]," dengan syarat berbeda, misalnya saldo minimum atau pengalaman trading. Metode perhitungan dan aset yang diakui juga berbeda."]],"example":"Anda memegang 2 BTC spot saat harga 60.000 USDT dan membuka short 2 BTC perpetual untuk melindungi nilainya. Di mode isolated dengan leverage 5x, short itu butuh margin 24.000 USDT. Dengan portfolio margin, sistem melihat bahwa jika BTC naik 15%, short rugi 18.000 USDT tetapi spot untung 18.000 USDT. Risiko bersihnya kecil, sehingga margin yang diminta bisa hanya beberapa ribu USDT untuk menutup risiko basis dan biaya.","mistakes":["Memakai efisiensi modal portfolio margin untuk menumpuk posisi berarah yang tidak terlindungi.","Mengira semua aset dihitung penuh sebagai jaminan, padahal banyak exchange memberi potongan nilai untuk altcoin.","Tidak memahami bahwa satu kegagalan pada model risiko bisa memicu likuidasi seluruh portofolio."],"faq":[{"q":"Siapa yang cocok memakai portfolio margin?","a":"Trader berpengalaman yang menjalankan strategi hedging, opsi, atau arbitrase dengan beberapa posisi yang saling mengimbangi. Pemula biasanya lebih aman memakai isolated margin."},{"q":"Apa beda portfolio margin dan cross margin?","a":"Cross margin menjumlahkan saldo sebagai jaminan bersama, sedangkan portfolio margin juga memperhitungkan bagaimana posisi saling mengimbangi risikonya dalam berbagai skenario harga."}],"title":"Apa itu portfolio margin? Arti dan cara kerjanya di kripto","description":"Pelajari portfolio margin di exchange kripto: cara menghitung margin dari risiko gabungan, manfaat untuk hedging, dan risikonya.","related":[["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["unified-trading-account","Akun trading terpadu (Unified Trading Account)","Akun trading terpadu adalah jenis akun bursa yang menggabungkan saldo spot, margin, futures, dan opsi dalam satu dompet, sehingga satu pool aset bisa dipakai sebagai margin untuk berbagai produk."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Margin silang: mengapa satu kerugian bisa memukul posisi Anda lainnya"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"id","term":"Short squeeze","aka":["squeeze","short-squeeze","pemerasan short"],"short":"Short squeeze adalah kenaikan harga yang cepat dan tajam karena banyak trader short terpaksa menutup posisi dengan membeli kembali aset, baik karena stop loss maupun likuidasi, sehingga mendorong harga naik lebih jauh.","body":[["Ketika banyak posisi short menumpuk, setiap kenaikan harga membuat sebagian short rugi. Short yang menutup posisi harus membeli, dan pembelian itu menaikkan harga, sehingga ",["stop loss","stop-loss"]," dan ",["likuidasi","liquidation"]," short berikutnya ikut terpicu. Efek berantai ini bisa membuat harga melonjak dalam hitungan menit."],["Tanda-tanda pasar rawan short squeeze antara lain ",["funding rate","funding-rate"]," negatif yang dalam, ",["open interest","open-interest"]," tinggi, ",["rasio long/short","long-short-ratio"]," yang condong ke short, dan harga yang mendekati ",["resistance","support-and-resistance"]," di mana banyak stop loss short diletakkan. Kebalikannya disebut long squeeze, saat banyak long dipaksa keluar dan harga jatuh cepat."],"Squeeze lebih mudah terjadi pada koin dengan likuiditas tipis. Di pasar seperti ini, pembelian relatif kecil saja bisa memicu rangkaian likuidasi."],"example":"Misalkan sebuah altcoin di 1,00 USDT punya short senilai 30 juta USDT di futures, dengan funding rate -0,1% per 8 jam. Berita positif mendorong harga naik ke 1,08. Short dengan leverage 10x yang masuk di sekitar 0,99 mulai dilikuidasi, dan pembelian paksa senilai 5 juta USDT menghantam order book yang tipis. Harga melompat ke 1,25 dalam 20 menit, kenaikan 25%, padahal berita awalnya hanya mendorong 8%.","mistakes":["Short koin kecil yang sudah dipenuhi posisi short dan funding sangat negatif.","Menaruh stop loss short tepat di atas resistance yang jelas, tempat stop loss banyak orang berkumpul.","Mengejar harga saat squeeze sedang berlangsung, lalu membeli di puncak lonjakan."],"faq":[{"q":"Bagaimana cara mengenali potensi short squeeze?","a":"Perhatikan funding rate yang sangat negatif, open interest tinggi, rasio long/short yang condong ke short, dan likuiditas tipis. Kombinasi ini menunjukkan banyak short yang bisa dipaksa keluar."},{"q":"Apa beda short squeeze dan long squeeze?","a":"Short squeeze adalah lonjakan harga yang memaksa short keluar. Long squeeze adalah penurunan tajam yang memaksa long dilikuidasi atau menutup posisi."}],"title":"Apa itu short squeeze di kripto? Arti dan contohnya","description":"Pelajari short squeeze di kripto: penyebab lonjakan harga, peran likuidasi dan funding, tanda-tanda awal, dan cara menghindarinya.","related":[["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["short-selling","Short selling (jual short)","Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["open-interest","Open interest (OI)","Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"id","term":"USDC (USD Coin)","aka":["USD Coin","USDC","Circle USDC"],"short":"USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange.","body":[["Circle menerbitkan laporan cadangan secara berkala, dan sebagian besar cadangan USDC dikelola dalam dana pasar uang yang diawasi. Pengguna institusi bisa mencetak dan menukarkan USDC langsung dengan Circle, sementara pengguna ritel umumnya memperolehnya di exchange atau ",["DeFi","defi"],"."],["USDC beredar di banyak jaringan seperti ",["Ethereum","ethereum"],", Solana, Base, Arbitrum, dan lainnya. Circle menyediakan CCTP, protokol untuk memindahkan USDC asli antar jaringan dengan cara membakar di chain asal dan mencetak di chain tujuan, sehingga tidak perlu versi wrapped. Di Uni Eropa, USDC tersedia di exchange yang beroperasi di bawah aturan ",["stablecoin","stablecoin"]," ",["MiCA","mica"],"."],["USDC juga pernah ",["depeg","depeg"],". Pada Maret 2023, ketika sebagian cadangan Circle tertahan di Silicon Valley Bank, harga USDC sempat turun jauh di bawah 1 dolar selama beberapa hari sebelum pulih. Seperti ",["USDT","usdt"],", alamat USDC bisa dibekukan oleh penerbit, dan nilai token bergantung pada kepercayaan terhadap cadangan."]],"example":"Misalnya Anda memegang 3.000 USDC di Ethereum dan ingin memakainya di Solana. Anda menyetor 3.000 USDC ke exchange lewat jaringan Ethereum, membayar gas dalam ETH, lalu menariknya lewat jaringan Solana dengan biaya penarikan contoh 1 USDC. Anda menerima 2.999 USDC asli di Solana. Sebelum itu, Anda memastikan dompet Solana memiliki sedikit SOL untuk biaya transaksi berikutnya.","mistakes":["Menganggap USDC tidak mungkin depeg karena diatur lebih ketat.","Mengirim USDC versi bridged ke exchange yang hanya menerima USDC asli di jaringan tersebut.","Lupa menyiapkan koin native jaringan untuk biaya gas sebelum memindahkan USDC."],"faq":[{"q":"Apa beda USDC dan USDT?","a":"Keduanya stablecoin dolar. USDC diterbitkan Circle dan USDT oleh Tether, dengan struktur cadangan, laporan, dan ketersediaan per wilayah yang berbeda. USDT biasanya lebih banyak pasangan di exchange, sedangkan USDC banyak dipakai di DeFi."},{"q":"Apakah USDC aman?","a":"USDC memiliki laporan cadangan berkala, tetapi tetap bergantung pada bank, kustodian, dan penerbit. Peristiwa Maret 2023 menunjukkan stablecoin besar pun bisa depeg sementara."}],"title":"Apa itu USDC? Arti stablecoin dari Circle","description":"Pelajari arti USDC, cara Circle menjaga cadangan, jaringan yang didukung, CCTP, serta risiko depeg dan pembekuan alamat.","related":[["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["usdt","USDT (Tether)","USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."],["mica","MiCA (regulasi aset kripto Uni Eropa)","MiCA adalah regulasi Uni Eropa tentang pasar aset kripto yang mengatur penerbit stablecoin dan penyedia jasa aset kripto (CASP) dengan satu set aturan untuk semua negara anggota."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"id","term":"Launchpool","aka":["Launch pool","farming token baru"],"short":"Launchpool adalah fitur bursa yang memberi Anda token proyek baru secara gratis sebagai imbalan karena mengunci aset tertentu, seperti BNB atau stablecoin, selama periode singkat.","body":["Binance Launchpool adalah contoh paling terkenal, dan bursa lain seperti Bybit, Bitget, atau OKX punya program serupa dengan nama berbeda. Anda menyetor aset ke pool, lalu imbalan token baru dibagi setiap jam atau setiap hari sesuai porsi Anda di pool tersebut.",["Berbeda dengan ",["launchpad","launchpad"],", Anda tidak membeli token. Aset yang dikunci tetap milik Anda dan biasanya bisa ditarik kapan saja atau setelah periode berakhir, tergantung aturan. Token hasil farming biasanya bisa diperdagangkan saat token resmi listing di bursa itu."],"Imbal hasilnya tidak tetap. Semakin banyak orang ikut, semakin kecil bagian Anda. Nilai token baru juga sangat fluktuatif setelah listing. Risiko lain adalah harga aset yang Anda kunci sendiri bisa turun selama periode tersebut."],"example":["Misalkan sebuah pool membagikan 1.000.000 token baru per hari kepada pengunci BNB, dan total BNB di pool 5.000.000. Jika Anda mengunci 10 BNB, porsi Anda 0,0002%, sehingga Anda mendapat 2 token per hari. Selama 5 hari, total 10 token. Jika ",["token listing","token-listing"]," di harga 0,50 ",["USDT","usdt"],", nilainya 5 USDT. Pada saat yang sama, jika BNB turun 3% dari 600 ke 582 USDT, nilai 10 BNB Anda turun 180 USDT. Jadi hasil farming jauh lebih kecil daripada pergerakan harga aset yang Anda kunci."],"mistakes":["Membeli aset yang harganya sudah naik tinggi hanya untuk ikut launchpool.","Menghitung imbal hasil dari jumlah peserta di awal, padahal pool bisa membesar.","Mengira token hasil launchpool pasti bernilai tinggi saat listing."],"faq":[{"q":"Apa beda launchpool dan launchpad?","a":"Di launchpool Anda mengunci aset dan menerima token gratis sebagai imbalan. Di launchpad Anda membeli token baru dengan aset Anda sebelum listing."},{"q":"Apakah aset di launchpool bisa ditarik kapan saja?","a":"Di banyak program bisa, tetapi aturan setiap bursa berbeda. Cek halaman detail pool untuk mengetahui periode penguncian dan cara penghitungan imbalan."}],"title":"Apa itu launchpool? Cara dapat token baru gratis","description":"Pelajari cara kerja launchpool di bursa kripto, cara menghitung bagian imbalan Anda, dan bedanya dengan launchpad.","related":[["launchpad","Launchpad (penjualan token)","Launchpad adalah platform penjualan token proyek baru sebelum diperdagangkan di bursa, di mana Anda membeli token dengan harga tetap memakai aset seperti USDT atau token bursa."],["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["airdrop","Airdrop","Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi."],["token-listing","Listing token","Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan."]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
